pub fn div(a: i64, b: i64) -> Result<i64, Error> {
    if b == 0 {
        return Err(Error::DivZero);
    }
    // |a| < 2^63, so a * 2^32 < 2^95: no overflow in i128.
    narrow((a as i128 * ONE_WIDE) / b as i128)
}

