pub fn line(s: Sums) -> Result<Line, Error> {
    let n = N_FIX;
    let mean_y = div(s.y, n)?;
    let num = sub(mul(n, s.xy)?, mul(s.x, s.y)?)?;
    let den = sub(mul(n, s.x2)?, mul(s.x, s.x)?)?;
    let slope = div(num, den)?;
    let intercept = div(sub(s.y, mul(slope, s.x)?)?, n)?;
    Ok(Line { mean_y, slope, intercept })
}

