pub fn linreg(p: &[(i64, i64); 10]) -> Result<Fit, Error> {
    let s = sums(p)?;
    let l = line(s)?;
    let q = sums_of_squares(p, l.slope, l.intercept, l.mean_y)?;
    let r_squared = sub(ONE, div(q.res, q.tot)?)?;
    Ok(Fit { slope: l.slope, intercept: l.intercept, r_squared })
}

